mapper.select:
select stock_qty from tb_warehouse_stock
where warehouse_no = #{warehouseNo}
  and goods_no = #{goodsNo}

mapper.update:
update tb_warehouse_stock
set stock_qty = stock_qty + #{qty}
where warehouse_no = #{warehouseNo}
  and goods_no = #{goodsNo}

update tb_warehouse_stock
set stock_qty = stock_qty - #{qty}
where warehouse_no = #{warehouseNo}
  and goods_no = #{goodsNo}
  and stock_qty >= #{qty}

update tb_warehouse_stock
set stock_qty = #{qty}
where warehouse_no = #{warehouseNo}
  and goods_no = #{goodsNo}
